p=R/'content/tieng-anh/tap-1/TA3_T1_U09.json';c=json.loads(p.read_text());fig=dict(path='content/assets/TA3_T1_U09_colour_cards.svg',caption='Ba thẻ A, B, C; hình SVG do dự án tự dựng.')
c['practice'][4]['figure']=fig;c['figures']=[fig];p.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
